import dev.hua.ptcglive.engine.*;
import dev.hua.ptcglive.engine.effect.*;
import dev.hua.ptcglive.engine.field.*;
import dev.hua.ptcglive.rules.*;
import java.util.*;

public final class NonPokemonBatch37Test {
    static final UUID A=GeneratedRuleBatch8Test.A,B=GeneratedRuleBatch8Test.B;
    static final String FOSSIL="sm5_en_134";
    static final List<String> IDS=List.of("sm10_en_165","sm11-5_en_065","sm6_en_107","sm7_en_133","sm9_en_153","sm9_en_154","swsh11_en_164","swsh11_en_194","swsh11_en_209","swsh3-5_en_064","swsh4_en_151");
    static void check(boolean ok,String why){if(!ok)throw new AssertionError(why);}
    static CardInstance card(ServerMatch m,UUID p,String id){return DynamicPassiveModifierTest.hand(m,p,id);}
    static void play(ServerMatch m){m.playTrainer(A,card(m,A,"trainer").instanceId(),null);}
    static void choose(ServerMatch m,List<UUID> ids){var q=m.effectCardPrompt(A);m.submitEffectCards(A,q.resolutionId(),q.step(),ids);}
    static void option(ServerMatch m,int option){var q=m.effectChoicePrompt(A);m.chooseEffectOption(A,q.resolutionId(),q.step(),option);}
    static void reveal(ServerMatch m){while(m.effectCardReveal()!=null){var r=m.effectCardReveal();m.acknowledgeEffectReveal(r.confirmingPlayer(),r.id());}}
    static void hidden(ServerMatch m){try{m.effectCardPrompt(B);throw new AssertionError("Opponent could inspect private choices");}catch(IllegalStateException expected){}}
    static void settle(ServerMatch m){NonPokemonBatch2Test.settle(m);}
    static ServerMatch game(String id){return game(id,List.of());}
    static ServerMatch game(String id,List<AbilityDefinition> abilities){return game(id,abilities,DeckDiscardTriggeredAbilityTest.trainer("SUPPORTER","{\"type\":\"draw\",\"amount\":2}"));}
    static ServerMatch game(String id,List<AbilityDefinition> abilities,TrainerProfile supporter){var trainer=NonPokemonBatch2Test.DATA.trainer(id).orElseThrow();String[] ids={"basic","basic","basic","energy","trainer","trainer","item","supporter",FOSSIL,"tool"};var defs=new ArrayList<CardDefinition>();
        for(String key:Arrays.stream(ids).distinct().toList())defs.add(new CardDefinition(key,key,key.equals("basic")?CardCategory.POKEMON:key.equals("energy")?CardCategory.ENERGY:CardCategory.TRAINER,key.equals("trainer")?trainer.category():key.equals("supporter")?TrainerCategory.SUPPORTER:key.equals("tool")?TrainerCategory.TOOL:Set.of("item",FOSSIL).contains(key)?TrainerCategory.ITEM:TrainerCategory.NONE,"H",Set.of("international"),key.equals("basic"),key.equals("energy"),60,Map.of(),EffectSupport.SUPPORTED,null));
        var draw=DeckDiscardTriggeredAbilityTest.trainer("ITEM","{\"type\":\"draw\",\"amount\":1}");var combat=new CombatCatalog(Map.of("basic",new PokemonProfile(500,0,null,null,0,null,0,1,List.of(GeneratedRuleBatch8Test.hit(100,false)),abilities,EnergyType.GRASS)),Map.of("energy",EnergyType.GRASS),Map.of("trainer",trainer,"item",draw,FOSSIL,draw,"supporter",supporter,"tool",DynamicPassiveModifierTest.plainTool()),Map.of());
        for(int seed=0;seed<200;seed++){var decks=new ArrayList<List<CardInstance>>();for(UUID p:List.of(A,B)){var cs=new ArrayList<CardInstance>();for(int i=0;i<60;i++)cs.add(new CardInstance(new UUID(p.getLeastSignificantBits(),i+1),p,ids[i%ids.length]));decks.add(cs);}var m=new ServerMatch(A,B,decks.get(0),decks.get(1),GeneratedRuleBatch8Test.RULES,new CardDatabase(defs),combat,new ServerRandom(seed));OpeningTestSupport.decideOrder(m,A,B);if(List.of(A,B).stream().anyMatch(p->m.privateView(p).hand().stream().filter(c->c.definitionId().equals("basic")).count()<2))continue;OpeningTestSupport.complete(m,A,B,1);m.drawCardsByEffect(A,A,22);m.drawCardsByEffect(A,B,22);m.endTurn(A);m.endTurn(B);if(List.of(A,B).stream().allMatch(p->Arrays.stream(ids).allMatch(key->m.privateView(p).hand().stream().anyMatch(c->c.definitionId().equals(key)))))return m;}throw new AssertionError("Window fixture unavailable");
    }
    static void top(ServerMatch m,UUID owner,CardInstance c){m.discardHandCardsByEffect(A,owner,List.of(c.instanceId()));m.recoverDiscardCardsByEffect(A,owner,new ServerMatch.CardSelectionPolicy(1,1,null,null,false,Set.of()),List.of(c.instanceId()),CardEffectDestination.DECK_TOP);}
    static ServerMatch aiGame(String id){var m=game(id);if(id.equals("sm9_en_153"))m.discardHandCardsByEffect(A,B,List.of(card(m,B,"item").instanceId()));if(Set.of("sm11-5_en_065","sm9_en_154").contains(id))m.discardHandCardsByEffect(A,B,m.privateView(B).hand().stream().filter(c->c.definitionId().equals("trainer")).map(CardInstance::instanceId).toList());return m;}
    public static void main(String[] args){windows();sisters();drone();label();fossil();sabrina();System.out.println("NonPokemonBatch37Test passed: private fixed windows on either owner, short deck selection, same-owner shuffle/top placement, optional Item-only discard, reveal-before-inspection, opponent discard-to-bottom, exact Fossil choice and copied Supporter without transferring its physical card");}
    static void windows(){for(String id:List.of("swsh3-5_en_064","sm10_en_165","sm7_en_133"))for(boolean opponent:List.of(false,true))for(boolean shortDeck:List.of(false,true)){
        if(!id.equals("sm7_en_133")&&opponent!=id.equals("sm10_en_165"))continue;var m=game(id);UUID owner=opponent?B:A,other=opponent?A:B;if(shortDeck)m.drawCardsByEffect(A,owner,m.privateView(owner).deck().size()-1);var before=List.copyOf(m.privateView(owner).deck());var untouched=List.copyOf(m.privateView(other).deck());int count=id.equals("sm10_en_165")?3:5;var window=before.subList(Math.max(0,before.size()-count),before.size());play(m);if(id.equals("sm7_en_133"))option(m,opponent?1:0);var q=m.effectCardPrompt(A);check(q!=null&&new HashSet<>(q.candidates()).equals(new HashSet<>(window)),"Private window scope/owner leaked or changed");hidden(m);var picked=q.candidates().getFirst();choose(m,List.of(picked.instanceId()));settle(m);check(m.privateView(owner).deck().getLast().equals(picked)&&new HashSet<>(m.privateView(owner).deck()).equals(new HashSet<>(before))&&m.privateView(other).deck().equals(untouched),"Window rearranged or transferred wrong owner's cards");
    }}
    static void sisters(){for(String id:List.of("swsh11_en_164","swsh11_en_194","swsh11_en_209"))for(boolean take:List.of(false,true)){
        var m=game(id);var item=card(m,B,"item");for(String kind:List.of("item","tool","energy","basic","supporter"))top(m,B,card(m,B,kind));var own=List.copyOf(m.privateView(A).deck());int size=m.privateView(B).deck().size(),random=m.randomTranscript().size();play(m);var q=m.effectCardPrompt(A);check(q.candidates().equals(List.of(item)),"Miss Fortune Sisters offered non-Item or outside-window card");choose(m,take?List.of(item.instanceId()):List.of());settle(m);check(m.privateView(B).discard().contains(item)==take&&m.privateView(B).deck().size()==size-(take?1:0)&&m.privateView(A).deck().equals(own)&&m.randomTranscript().size()>random,"Sisters payment destination or mandatory remainder shuffle");
    }}
    static void drone(){var m=game("swsh4_en_151");var before=List.copyOf(m.privateView(B).deck());var hand=List.copyOf(m.privateView(B).hand());play(m);reveal(m);var q=m.effectCardPrompt(A);check(q.candidates().equals(List.of(before.getLast())),"Drone inspected wrong deck/window");hidden(m);choose(m,List.of(before.getLast().instanceId()));settle(m);check(m.privateView(B).deck().equals(before)&&m.privateView(B).hand().equals(hand),"Drone moved inspected or revealed cards");
        var empty=game("swsh4_en_151");empty.discardHandCardsByEffect(A,B,empty.privateView(B).hand().stream().map(CardInstance::instanceId).toList());check(!empty.canPlayTrainer(A,card(empty,A,"trainer").instanceId(),null),"Drone inspected deck without revealing any hand cards");
    }
    static void label(){var m=aiGame("sm9_en_153");var original=List.copyOf(m.privateView(B).deck());var chosen=m.privateView(B).discard().getLast();play(m);check(m.effectCardPrompt(A).candidates().contains(chosen),"Return Label wrong discard owner");choose(m,List.of(chosen.instanceId()));settle(m);check(m.privateView(B).deck().getFirst().equals(chosen)&&m.privateView(B).deck().subList(1,m.privateView(B).deck().size()).equals(original)&&!m.privateView(B).discard().contains(chosen)&&!m.privateView(A).hand().contains(chosen),"Return Label did not return to original owner's deck bottom");}
    static void fossil(){for(int branch:List.of(0,1)){var m=game("sm6_en_107");if(branch==1)m.discardHandCardsByEffect(A,A,List.of(card(m,A,FOSSIL).instanceId()));play(m);option(m,branch);var q=m.effectCardPrompt(A);check(!q.candidates().isEmpty()&&q.candidates().stream().allMatch(c->c.definitionId().equals(FOSSIL)),"Fossil Map allowed wrong identity");var chosen=q.candidates().getFirst();choose(m,List.of(chosen.instanceId()));settle(m);check(m.privateView(A).hand().contains(chosen),"Fossil Map failed chosen source transfer");}}
    static void sabrina(){for(String id:List.of("sm11-5_en_065","sm9_en_154"))for(boolean copy:List.of(false,true)){var m=game(id);var chosen=card(m,B,"supporter");int own=m.privateView(A).hand().size();var other=List.copyOf(m.privateView(B).hand());play(m);reveal(m);var q=m.effectCardPrompt(A);check(q.candidates().stream().allMatch(c->m.cardDefinition(c.definitionId()).trainerCategory()==TrainerCategory.SUPPORTER)&&q.candidates().contains(chosen),"Sabrina offered non-Supporter or missed revealed card");choose(m,copy?List.of(chosen.instanceId()):List.of());settle(m);check(m.privateView(B).hand().equals(other)&&m.privateView(A).hand().size()==own-1+(copy?2:0),"Sabrina copied wrong controller/effect or took physical card");check(!m.canPlayTrainer(A,card(m,A,"trainer").instanceId(),null),"Sabrina did not consume Supporter use");}}
}
